def can_tile_board(n, board):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n and board[x][y] == '.'

    def place_piece(x, y, dx, dy):
        for i in range(5):
            nx, ny = x + dx[i], y + dy[i]
            if not is_valid(nx, ny):
                return False
            board[nx][ny] = '#'
        return True

    def remove_piece(x, y, dx, dy):
        for i in range(5):
            nx, ny = x + dx[i], y + dy[i]
            board[nx][ny] = '.'

    def backtrack(x, y):
        if x == n:
            return True
        if y == n:
            return backtrack(x + 1, 0)
        if board[x][y] == '#':
            return backtrack(x, y + 1)

        # Try placing the piece in all 4 orientations
        for dx, dy in [(-1, 0), (0, -1), (1, 0), (0, 1)]:
            if place_piece(x, y, dx, dy):
                if backtrack(x, y + 1):
                    return True
                remove_piece(x, y, dx, dy)

        return False

    # Convert board to list of lists for mutability
    board = [list(row) for row in board]

    if backtrack(0, 0):
        return "YES"
    else:
        return "NO"

