def can_tile_board(n, board):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n and board[x][y] == '.'

    def dfs(x, y, visited):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if is_valid(nx, ny):
                    stack.append((nx, ny))

    # Define the relative positions of the five tiles in the piece
    directions = [
        (0, 0), (0, 1), (0, 2), (1, 1), (2, 1)
    ]

    # Count the number of free cells
    free_cells = sum(row.count('.') for row in board)

    # If the number of free cells is not divisible by 5, it's impossible to tile
    if free_cells % 5 != 0:
        return "NO"

    # Find all connected components of free cells
    visited = set()
    components = 0
    for i in range(n):
        for j in range(n):
            if board[i][j] == '.' and (i, j) not in visited:
                dfs(i, j, visited)
                components += 1

    # If there is more than one connected component of free cells, it's impossible to tile
    if components > 1:
        return "NO"

    return "YES"

