    def dfs(x, y, piece, visited):
        if x < 0 or x >= n or y < 0 or y >= n or board[x][y] == '#' or (x, y) in visited:
            return False
        visited.add((x, y))
        if len(visited) == 5:
            return True
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if dfs(nx, ny, piece, visited):
                return True
        visited.remove((x, y))
        return False

    def place_piece(x, y):
        visited = set()
        if dfs(x, y, piece, visited):
            for px, py in visited:
                board[px] = board[px][:py] + '#' + board[px][py+1:]
            return True
        return False

    piece = [(0, 0), (0, 1), (1, 0), (1, 1), (2, 0)]
    free_cells = [(i, j) for i in range(n) for j in range(n) if board[i][j] == '.']

    if len(free_cells) % 5 != 0:
        return "NO"

    for cell in free_cells:
        if place_piece(cell[0], cell[1]):
            break
    else:
        return "NO"

    for i in range(n):
        for j in range(n):
            if board[i][j] == '.':
                return "NO"

    return "YES"

